// Array to hold all raindrop objects
var d = [];

function setup() { //runs once at the beginning
  createCanvas(windowWidth, windowHeight); // create full-window canvas (i like this but need image to scale better)

// Generate initial raindrops, random horizontal position, random vertical position, random speed factor for variety
  for (var i = 0; i < 500; i++) {
    d.push(new Drop(random(0, windowWidth), random(0, windowHeight), random(2, 4)));
		// 500 raindrops are created at the start and reused
  }
}

function draw() { // this runs continuously to animate the scene

  // Fading effect: draw a semi-transparent black rectangle	
  noStroke();
  fill(0, 25);
  rect(0, 0, width, height);

	// Update and draw all raindrops
  for (var i = 0; i < d.length; i++) {
    d[i].displ(); //call the raindrop's display/update function
  }
}

function Drop(x, y, sp) {
  var x1 = x; // horizontal position of drop
  var y1 = y; // vertical position
  var x2; //  endpoint
  var y2; //  endpoint
  var s = sp; // speed 

  this.displ = function() { // displ() is the function called each frame to move and draw the drop
    // converts mouse position 
		var mx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / 120;  // dividing by 120 slows it down
    if (mx <= 0) {
      mx = 0.5; // default speed - no mouse
    }

    y1 = y1 + s * mx; // scales speed according to mouse position
    x2 = x1;
    y2 = y1 + 30; // length of raindrops, change if they're too long/short

    stroke(200);
    line(x1, y1, x2, y2); // draws raindrop

    if (y1 >= windowHeight - 80) { // did the drop hit the ground?
			noFill();
      noStroke();
      fill(255, 150);
      ellipse(x1, windowHeight - random(5, 50), random(2, 5), random(1, 4)); // then draw a splash

			// renews the drop by sending it back to the top (no need to generate new ones)
			x1 = random(0, windowWidth);
      y1 = -120;
    }
  }

}

